css:
@import url("https://fonts.googleapis.com/css2?family=Comfortaa:wght@600;700&family=Open+Sans:wght@400;600;700&display=swap");
:root{--mn:#3CCF91;--mn2:#1F9E68;--sk:#E6F7FF;--nv:#1E3A5F;--ink:#16263A;--gr:#56637A;--ln:#D8E6EF;--h:"Comfortaa",system-ui,sans-serif;--b:"Open Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1.1}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--mn);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--nv);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative}.logo{font-family:var(--h);font-weight:700;font-size:24px;text-decoration:none;color:var(--nv);display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;align-items:center;font-weight:600}.menu a{text-decoration:none}.menu .cta{background:var(--mn);padding:9px 18px;border-radius:30px}
.burger{display:none;background:none;border:2px solid var(--nv);width:44px;height:40px;border-radius:12px;font-size:20px;cursor:pointer}
.hero{background:var(--sk);border-radius:0 0 50px 50px;padding:40px 0 70px}.hg{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}.hg>*{min-width:0}
.hero h1{font-size:clamp(40px,5.2vw,68px);color:var(--nv)}.hero p{font-size:20px;color:var(--gr);margin:18px 0 26px;max-width:28em}
.btn{display:inline-block;background:var(--nv);color:#fff;text-decoration:none;font:700 17px var(--b);padding:14px 24px;border-radius:40px;border:0;cursor:pointer}.btn.m{background:var(--mn);color:var(--ink)}
.row{display:flex;gap:12px;flex-wrap:wrap}
.pics{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pics img{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:30px}.pics img:last-child{margin-top:40px}
.promise{display:flex;gap:18px;flex-wrap:wrap;margin-top:26px;font-size:15px;color:var(--gr)}.promise span:before{content:"✓ ";color:var(--mn2);font-weight:700}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:28px}.sh h2{font-size:clamp(32px,4.2vw,50px);color:var(--nv)}.sh p{color:var(--gr);margin:10px 0 0}
.types{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.ty{border:2px solid var(--ln);border-radius:22px;padding:22px}.ty h3{font-size:22px;color:var(--nv)}.ty p{color:var(--gr);margin:8px 0 0;font-size:16px}
.calc{background:var(--sk)}.cg{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:start}.cg>*{min-width:0}
.box{background:#fff;border-radius:24px;padding:26px}.lb{display:block;font-weight:700;font-size:16px;margin:0 0 8px}
.seg{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.seg button{font:600 15px var(--b);border:2px solid var(--ln);background:#fff;border-radius:30px;padding:8px 14px;cursor:pointer;color:var(--ink)}.seg button[aria-pressed=true]{background:var(--nv);color:#fff;border-color:var(--nv)}
.cnt{display:flex;align-items:center;gap:12px;margin-bottom:18px}.cnt button{width:40px;height:40px;border-radius:50%;border:2px solid var(--nv);background:#fff;font-size:20px;cursor:pointer}.cnt output{font-family:var(--h);font-size:24px;min-width:26px;text-align:center}.cnt span{flex:1;font-weight:600}
.ex{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px}.ex label{position:relative;cursor:pointer}.ex input{position:absolute;opacity:0;width:1px;height:1px;left:0;top:0}.ex span{display:block;border:2px solid var(--ln);border-radius:30px;padding:7px 14px;font-size:15px}.ex input:checked+span{background:var(--mn);border-color:var(--mn)}.ex input:focus-visible+span{outline:3px solid var(--nv)}
.res{background:var(--nv);color:#fff;border-radius:24px;padding:26px;position:sticky;top:16px}.res small{color:#A9BED6}.res .big{font-family:var(--h);font-size:52px;color:var(--mn);margin:6px 0}.res ul{list-style:none;padding:0;margin:12px 0}.res li{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #2F4C72;font-size:15px}
.res label{display:block;font-size:14px;color:#A9BED6;margin:10px 0 4px}.res input,.res select{width:100%;font:16px var(--b);padding:10px;border:0;border-radius:10px;margin-bottom:6px}
.res .btn{background:var(--mn);color:var(--ink);width:100%;text-align:center;margin-top:10px}.msg{visibility:hidden;margin:10px 0 0;font-weight:600;color:var(--mn);font-size:15px}.msg.on{visibility:visible}
.rv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.rv blockquote{margin:0;background:var(--sk);border-radius:22px;padding:22px}.rv p{margin:0 0 10px}.rv cite{font-style:normal;color:var(--gr);font-size:15px}
footer{padding:26px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.cg{grid-template-columns:1fr}.types,.rv{grid-template-columns:1fr}.res{position:static}.pics{max-width:420px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:#fff;flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.hero{border-radius:0 0 30px 30px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const S={bed:2,bath:1};let t=1,f=.1;
function calc(){$('bed').textContent=S.bed;$('bath').textContent=S.bath;const hrs=(1.5+S.bed*.5+S.bath*.5)*t,base=hrs*18;const disc=t===1?base*f:0;const ex=[...$('ex').querySelectorAll('input:checked')];const exs=ex.reduce((a,x)=>a+ +x.dataset.p,0);const tot=base-disc+exs;
$('tp').textContent='£'+Math.round(tot);$('th').textContent=`About ${hrs.toFixed(1).replace('.0','')} hours with one cleaner`;
$('tlst').innerHTML=`<li><span>Cleaning, ${S.bed} bed, ${S.bath} bath</span><span>£${Math.round(base)}</span></li>${disc?`<li><span>Regular discount</span><span>−£${Math.round(disc)}</span></li>`:''}${ex.map(x=>`<li><span>${x.dataset.n}</span><span>£${x.dataset.p}</span></li>`).join('')}`}
document.querySelectorAll('.cnt button').forEach(b=>b.onclick=()=>{const k=b.dataset.c;S[k]=Math.max(k==='bed'?0:1,Math.min(6,S[k]+ +b.dataset.d));calc()});
$('ty').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('ty').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));t=+b.dataset.t;calc()};
$('fq').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('fq').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));f=+b.dataset.f;calc()};$('ex').addEventListener('change',calc);calc();
const d=new Date(Date.now()+3*864e5);$('bd').value=d.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);
$('bf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Booked, ${$('bn').value}! Your first clean is ${$('bd').value}. We'll text you your cleaner's name.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
